<script>
import RiftMerchant from '../drift/RiftMerchant.vue';
import BagItemIcon from '../menu/BagItemIcon.vue';
import {BAG_POCKETS,bagPocket} from '@/services/bagPockets';
export default {
  name:'ShopPanel',components:{RiftMerchant,BagItemIcon},
  props:{visible:Boolean,catalog:{type:Array,default:()=>[]},items:{type:Array,default:()=>[]},metadata:{type:Object,default:()=>({})},location:String,money:{type:Number,default:0},loading:Boolean,error:String,language:String,expedition:Boolean,merchant:Object,driftCatalogue:Object,drifts:{type:Array,default:()=>[]},equipped:{type:Array,default:()=>[]}},
  data(){return {active:'balls',query:'',quantities:{},trainingFilter:'vitamins',previousFocus:null,pendingFocus:null,trainingTabs:[{key:'vitamins',name:'Vitamines',en:'Vitamins'},{key:'iv',name:'Relances IV',en:'IV rolls'},{key:'ev',name:'Reset EV',en:'EV reset'}]};},
  computed:{
    english(){return this.language==='en';},
    categories(){const order=['balls','medicine','berries','field','held','evolution','training','machines'];const result=order.map(key=>({...BAG_POCKETS.find(p=>p.key===key),count:this.catalog.filter(i=>bagPocket(i)===key).length})).filter(p=>p.count||p.key==='training'&&this.metadata.specialty==='training');if(this.expedition&&this.merchant)result.push({key:'drifts',name:'Drifts',en:'Drifts',count:this.merchant.offers?.length||0});return result.length?result:[{key:'balls',name:'Balls',en:'Balls',count:0}];},
    current(){return this.categories.find(c=>c.key===this.active)||this.categories[0];},
    filteredTrainingAvailable(){return this.catalog.some(i=>bagPocket(i)==='training');},
    filteredCatalog(){const q=this.query.trim().toLocaleLowerCase();return this.catalog.filter(i=>q?`${i.name} ${i.description}`.toLocaleLowerCase().includes(q):bagPocket(i)===this.active&&(this.active!=='training'||this.trainingKind(i)===this.trainingFilter));},
    stageLabel(){if(this.metadata.department)return this.english?`Level ${this.metadata.department} · ${['Supplies','Training','Strategy','Berries'][this.metadata.department-1]}`:this.metadata.name;return this.english?(this.expedition?'Expedition supplies':['Essentials','Lake trainer','Seasoned traveller','Trained team','Expert trainer','The final stretch'][this.metadata.tier||0]):this.metadata.name||(this.expedition?'Fournitures d’expédition':'Fournitures de voyage');},
    nextUnlock(){if(this.metadata.department)return this.english?'Each level has its own counter. Purchased items go into your bag.':this.metadata.next;return this.english?(this.expedition?'For this expedition only.':['Defeat Mounir for more supplies.','Defeat Hoze for evolution stones and Ultra Balls.','Defeat Raphael for advanced medicine.','Defeat Ana for Max Potions and Leppa Berries.','Defeat Wanda for the Whitepeak Training department.','Whitepeak’s Training department can help you prepare for 7p.'][this.metadata.tier||0]):this.metadata.next||'Le stock s’étoffe au fil de tes victoires d’arène.';}
  },
  watch:{loading(value){if(!value&&this.visible)this.$nextTick(()=>{if(!this.$refs.dialog?.contains(document.activeElement)){const button=this.pendingFocus?this.$refs.dialog?.querySelector(`[data-shop-item="${this.pendingFocus}"] button:not(:disabled)`):null;(button||this.$refs.close)?.focus({preventScroll:true});}this.pendingFocus=null;});},visible(value){if(value){this.previousFocus=document.activeElement===document.body?this.$parent.$el.querySelector('.location-shop-btn'):document.activeElement;this.active='balls';this.query='';this.trainingFilter='vitamins';this.$nextTick(()=>this.$refs.close?.focus({preventScroll:true}));}else this.restoreFocus();},catalog:{immediate:true,handler(items){for(const i of items||[])if(!this.quantities[i.key])this.$set(this.quantities,i.key,1);this.$nextTick(()=>{if(!this.categories.some(c=>c.key===this.active))this.active=this.categories[0].key;});}}},
  beforeDestroy(){if(this.visible)this.restoreFocus();},
  methods:{buy(item){this.pendingFocus=item.key;this.$emit('buy',{itemKey:item.key,quantity:item.purchaseLimit?1:this.quantityFor(item.key)});},pocket:bagPocket,trainingKind(i){return i.fieldUse?.ivReroll?'iv':i.fieldUse?.effortReset?'ev':'vitamins';},select(key){this.active=key;this.query='';this.$nextTick(()=>{if(this.$refs.stock)this.$refs.stock.scrollTop=0;});},quantityFor(key){return Number(this.quantities[key])||1;},totalFor(item){return item.price*(item.purchaseLimit?1:this.quantityFor(item.key));},ownedQuantity(key){return Number(this.items.find(i=>i.key===key)?.quantity)||0;},restoreFocus(){const previous=this.previousFocus;this.$nextTick(()=>{if(previous?.isConnected)previous.focus({preventScroll:true});});},moveCategory(e,key){if(!['ArrowLeft','ArrowRight','ArrowUp','ArrowDown','Home','End'].includes(e.key))return;e.preventDefault();const n=this.categories.length,i=this.categories.findIndex(c=>c.key===key),next=e.key==='Home'?0:e.key==='End'?n-1:(i+(['ArrowLeft','ArrowUp'].includes(e.key)?-1:1)+n)%n;this.select(this.categories[next].key);this.$nextTick(()=>document.getElementById(`shop-category-${this.active}`)?.focus());},handleKeydown(e){if(e.key==='Escape'){e.preventDefault();e.stopPropagation();this.$emit('close');}if(e.key!=='Tab')return;const nodes=[...this.$refs.dialog.querySelectorAll('button:not(:disabled),select:not(:disabled),input,[tabindex="0"]')].filter(n=>n.getClientRects().length),first=nodes[0],last=nodes[nodes.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}}
};
</script>
